{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "LSD absolute oral bioavailability was 80% (72–90%) in healthy participants after oral dosing compared with intravenous administration, supporting F ≥ 20%."
    },
    {
      "card_ids": ["C04"],
      "claim": "Tolfenamic acid absolute oral bioavailability was 63.2% after a 100 mg oral dose compared with intravenous administration in healthy female volunteers, supporting F ≥ 20%."
    },
    {
      "card_ids": ["C14"],
      "claim": "Magnesium L-lactate ER caplet evidence is mixed: serum-based absolute bioavailability was 12.49% in the fed state (below threshold), while urine-based values were 38.11–40.99% and fasted serum was 20.26%, creating uncertainty around the threshold."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C14"],
  "decision_summary": "Direct absolute oral bioavailability measurements in humans for LSD (80%) and tolfenamic acid (63.2%) support high bioavailability at the F ≥ 20% threshold. One mixed magnesium ER caplet record with a serum fed value below 20% lowers confidence but does not overturn the positive direction.",
  "evidence_gaps": [
    "Molecule 7 magnesium ER caplet has conflicting serum- versus urine-based absolute bioavailability values, with the fed serum value below the 20% threshold.",
    "Some records are qualitative (e.g., 'good' or 'complete' bioavailability) and do not provide numeric threshold-relevant measurements."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C24", "C04"],
  "revision_action": "initial",
  "supportive_card_ids": ["C24", "C04"]
}

